window.FILM_WORK_PROMPTS={"work_id":"src-d0466628fb495ee0","records":[{"work_id":"src-d0466628fb495ee0","frame_id":"FG-d7506079a0e79a7c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Red_Island_07.jpg","source_page":"https://film-grab.com/2025/01/12/red-island/","scene":"红土庭院中摆放着铺白桌布的长餐桌，周围环绕着白色塑料椅和木椅，左下角有一张矮木桌，背景是石墙房屋与绿植。","analysis":"画面采用高角度俯视构图，长餐桌呈对角线延伸占据视觉中心。桌椅大小比例协调，白色桌布与红褐色地面形成强烈色彩对比。光线柔和均匀，无明显阴影，整体色调偏暖，呈现出一种静谧的午后氛围。","prompt":"高角度俯拍视角，展示一处红土庭院。画面中心是一张铺着白色桌布的长餐桌，桌上摆放着餐具和食物。餐桌周围散落着几把白色塑料椅和深色木椅，以及几个白色方凳。左下角有一张矮木桌，上面放着盘子和碗。背景是一栋单层建筑，下半部为石砌墙基，上半部为白色墙面，设有带铁栅栏的窗户。庭院角落有绿色植物和卷起的水管，地面呈现粗糙的红褐色质感，光线自然柔和。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:36:52+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Red_Island_07.jpg","observed_dimensions":[1476,1076],"source_thumbnail_dimensions":[500,364],"source_image_match_mae":0.146,"observed_resolution":"normal","observation_limits":[],"id":"VP-d6d48368032ac516","origin":"visual"},{"work_id":"src-d0466628fb495ee0","frame_id":"FG-d7bc783f4da7825f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Red_Island_20.jpg","source_page":"https://film-grab.com/2025/01/12/red-island/","scene":"教室内，前景一名穿格纹衬衫的男孩与右侧黑发女孩并排坐着，目光投向左前方。背景虚化处可见其他学生身影，环境光线柔和，色调偏暖。","analysis":"画面采用浅景深，焦点清晰落在中间男孩面部，右侧女孩及背景人物均处于虚化状态。人物仅上半身可见，男孩双臂交叠于身前，身体微侧。光线从左侧窗户射入，在男孩面部形成柔和的明暗过渡，整体色调偏暖黄，背景呈现大面积模糊的亮色块。","prompt":"一张写实风格的室内静帧，画面聚焦于一名深褐色短发男孩，身穿米色格纹衬衫，双臂交叠，神情专注地望向左侧。右侧前景是一名虚化的黑发女孩，身穿红色上衣。背景中隐约可见其他模糊的学生身影。环境为教室，左侧有明亮的窗户光源，光线柔和地打在男孩脸上，形成自然的阴影。整体色调温暖，景深极浅，背景虚化严重，突出了前景人物的轮廓与神态。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:36:59+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Red_Island_20.jpg","observed_dimensions":[1476,1076],"source_thumbnail_dimensions":[500,364],"source_image_match_mae":0.13,"observed_resolution":"normal","observation_limits":[],"id":"VP-890854daab03e3f3","origin":"visual"},{"work_id":"src-d0466628fb495ee0","frame_id":"FG-b2c101c2c279a791","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Red_Island_33.jpg","source_page":"https://film-grab.com/2025/01/12/red-island/","scene":"一艘深色金属船体漂浮在宽阔平静的水面上，船身周围激起白色水花。远处是低矮的土黄色房屋、树木和植被，上方是大面积灰白色的云层天空。","analysis":"画面采用横向构图，水平线位于画面中部偏下位置。主体是一艘位于画面中下方的金属船体，船身呈梯形，内部可见浅色物体。船体左侧水面有明显的白色浪花和扰动痕迹。背景是远处的河岸，分布着低矮的土黄色建筑和绿色树木。天空占据画面上半部分，云层厚重，光线柔和漫射，整体色调偏灰绿和土黄，呈现出一种平静而略显压抑的视觉氛围。","prompt":"这是一张写实风格的风景摄影图。画面主体是一艘漂浮在宽阔水面上的深色金属船体，船身呈梯形结构，内部可见浅色物体。船体左侧水面激起明显的白色浪花和扰动痕迹，显示其正在移动或受到水流冲击。背景是远处的河岸，分布着低矮的土黄色建筑和绿色树木，植被稀疏。天空占据画面上半部分，云层厚重，光线柔和漫射，整体色调偏灰绿和土黄，呈现出一种平静而略显压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:37:08+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Red_Island_33.jpg","observed_dimensions":[1476,1076],"source_thumbnail_dimensions":[500,364],"source_image_match_mae":0.123,"observed_resolution":"normal","observation_limits":[],"id":"VP-515f670ee214156e","origin":"visual"},{"work_id":"src-d0466628fb495ee0","frame_id":"FG-b86fd50183e7ba55","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Red_Island_46.jpg","source_page":"https://film-grab.com/2025/01/12/red-island/","scene":"一个被绳索捆绑、面部下半部分被蓝布蒙住的木偶人物，身穿马甲和格子围巾，站在昏暗的砖墙背景前。","analysis":"画面主体为木偶人物的上半身，头部和肩部占据画面中心。人物被绳索交叉捆绑在胸前，颈部系着红格纹围巾。背景是模糊的深色砖墙，环境昏暗。光线从上方投射，照亮了人物的额头和头发，而面部下半部分和身体大部分处于阴影中，整体色调偏暖黄与深褐。","prompt":"昏暗室内，一个木偶人物上半身特写，黑色乱发，浓眉，眼睛圆睁，嘴部被蓝灰色布条紧紧蒙住。身穿棕色马甲，内搭浅色长袖，颈部系着红白格纹围巾。胸前被粗糙的麻绳交叉捆绑。背景是模糊的深褐色砖墙，光线从上方投射，照亮额头和头发，整体色调阴暗，带有暖黄色调。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:37:15+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Red_Island_46.jpg","observed_dimensions":[1476,1076],"source_thumbnail_dimensions":[500,364],"source_image_match_mae":0.124,"observed_resolution":"normal","observation_limits":[],"id":"VP-053c59e6cfc6431f","origin":"visual"},{"work_id":"src-d0466628fb495ee0","frame_id":"FG-d30fa8e3360398b1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Red_Island_59.jpg","source_page":"https://film-grab.com/2025/01/12/red-island/","scene":"昏暗室内，左侧拱形彩色玻璃窗，右侧墙面投射出强烈的黄蓝彩色光束，光束下有一张铺白布的小桌，桌上摆放着瓶罐和干花，前景是模糊的深色长椅。","analysis":"画面采用侧光构图，左侧窗户与右侧墙面形成对角线视觉引导。强烈的彩色光束从左上方向右下方投射，在墙面上形成大面积的高光区域，与周围深沉的阴影形成强烈对比。前景的长椅处于暗部，仅可见轮廓，增强了空间的纵深感。","prompt":"昏暗的室内空间，左侧墙壁有一扇拱形彩色玻璃窗，玻璃呈现红蓝黄等色块。一道强烈的彩色光束从窗户射入，在右侧墙壁上投射出巨大的黄色与蓝色光斑，光斑中心明亮，边缘渐暗。光束下方有一张铺着白色桌布的小方桌，桌上摆放着几个玻璃瓶和插着干花的容器。前景是几排深色的木质长椅，处于阴影中，轮廓模糊。右侧背景隐约可见一个深色的金属架结构。整体色调偏暖，光影对比强烈，营造出一种静谧而神秘的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T12:37:22+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Red_Island_59.jpg","observed_dimensions":[1476,1076],"source_thumbnail_dimensions":[500,364],"source_image_match_mae":0.132,"observed_resolution":"normal","observation_limits":[],"id":"VP-e4e48c9d03066f0f","origin":"visual"}]};